function statusOf(p){return p.stock===0?"Out of Stock":p.stock<=7?"Low Stock":"Available"}
function vendorOf(id){return getVendors().find(v=>v.id===id)||{id,name:'Vendor',stall:'Unknown stall',no:'—',cat:''}}
function money(n){return "₱"+Number(n).toLocaleString()}
function toast(msg){const box=$("#toast");box.innerHTML="";const d=document.createElement("div");d.className="toast-item";d.textContent=msg;box.append(d);setTimeout(()=>d.remove(),3000)}
function escapeHTML(v=""){return String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
async function hashPassword(password){if(window.crypto?.subtle){const data=new TextEncoder().encode(password);const digest=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')}let h=2166136261;for(const ch of String(password)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return 'demo-'+(h>>>0).toString(16)}
function canAccess(routeId){if(routeId==="admin-dashboard")return currentUser?.role==="admin"&&currentUser?.adminVerified===true;if(routeId==="vendor-dashboard")return currentUser?.role==="vendor";if(["profile","reservations","settings"].includes(routeId))return !!currentUser;return true}
function deny(){toast("Access denied: your account is not authorized for this area.");$(".page.active")?.classList.remove("active");$("#home").classList.add("active");document.body.classList.remove('portal-mode');history.replaceState(null,'','#home')}
const PORTAL_ROUTES=['customer-dashboard','vendor-dashboard','admin-dashboard','profile','reservations','settings','products','vendors','gallery'];
const ROUTE_ALIAS={'vendor-inventory':'vendor-dashboard'};
function route(rawId,fromPop){const id=ROUTE_ALIAS[rawId]||rawId;if(!canAccess(id)){if(!currentUser&&["profile","reservations","settings"].includes(id))openModal("authModal");else deny();return}$$('.page').forEach(p=>p.classList.remove('active'));const page=$("#"+id)||$("#home");page.classList.add('active');$$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===rawId));document.body.classList.toggle('portal-mode',!!currentUser&&PORTAL_ROUTES.includes(id));$("#nav").classList.remove('open');window.scrollTo({top:0,behavior:'auto'});if(id==='products')renderProducts();if(id==='profile')renderProfile();if(id==='reservations')renderReservations();if(id==='customer-dashboard')renderCustomerDashboard();if(id==='vendor-dashboard')renderVendorDashboard();if(id==='admin-dashboard')renderAdmin();if(id==='settings')renderRoleSettings();if(!fromPop&&location.hash!=='#'+rawId)history.pushState(null,'','#'+rawId);if(rawId==='vendor-inventory')setTimeout(()=>$("#vendorInventory")?.scrollIntoView({behavior:'smooth',block:'start'}),60)}
