function renderCategories(){$("#categoryGrid").innerHTML=categories.map(([n,i])=>`<button class="category-card" data-cat="${n}"><div class="category-icon"><span class="material-symbols-outlined">${i}</span></div><b>${n}</b><small>Browse products</small></button>`).join('');$$('.category-card').forEach(b=>b.onclick=()=>{$("#categoryFilter").value=b.dataset.cat;route('products');renderProducts()});$("#categoryFilter").innerHTML='<option value="">All Categories</option>'+categories.map(c=>`<option>${c[0]}</option>`).join('');$("#pCategory").innerHTML=categories.map(c=>`<option>${c[0]}</option>`).join('')}
function canReserveRole(){return !currentUser||currentUser.role==='customer'}
function productCard(p){const v=vendorOf(p.vendorId),st=statusOf(p),cls=st==='Low Stock'?'low':st==='Out of Stock'?'out':'';return `<article class="product-card"><div class="product-image" style="background-image:url('${escapeHTML(p.image||'')}')"><span class="status ${cls}">${st}</span></div><div class="product-body"><small>${escapeHTML(p.category)}</small><div class="product-title"><h3>${escapeHTML(p.name)}</h3><span class="price">${money(p.price)}/${escapeHTML(p.unit)}</span></div><small>${p.stock} ${escapeHTML(p.unit)} available</small><div class="vendor-line">${mi('storefront')} ${escapeHTML(v.stall)} • Stall ${v.no}</div><div class="card-actions"><button class="btn btn-outline" onclick="viewProduct(${p.id})">View</button>${canReserveRole()?`<button class="btn btn-primary" ${p.stock===0?'disabled':''} onclick="reserve(${p.id})">Reserve</button>`:''}</div></div></article>`}
function renderFeatured(){$("#featuredProducts").innerHTML=products.filter(p=>p.stock>0).slice(0,4).map(productCard).join('')||'<div class="empty-note">No products listed yet. Products appear here as soon as vendors add them.</div>'}
function renderProducts(){let arr=[...products],q=$("#productSearch").value.toLowerCase(),cat=$("#categoryFilter").value,st=$("#statusFilter").value,sort=$("#sortFilter").value;if(q)arr=arr.filter(p=>{let v=vendorOf(p.vendorId);return [p.name,p.category,v.name,v.stall].join(' ').toLowerCase().includes(q)});if(cat)arr=arr.filter(p=>p.category===cat);if(st)arr=arr.filter(p=>statusOf(p)===st);if(sort==='az')arr.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='low')arr.sort((a,b)=>a.price-b.price);if(sort==='high')arr.sort((a,b)=>b.price-a.price);if(sort==='new')arr.sort((a,b)=>b.id-a.id);$("#allProducts").innerHTML=arr.map(productCard).join('')||'<p>No products found.</p>';$("#resultCount").textContent=`${arr.length} product${arr.length!==1?'s':''}`}
