function renderVendors(){const card=v=>`<article class="vendor-card"><div class="vendor-avatar">${mi(v.icon)}</div><div class="vendor-card-info"><small>STALL ${v.no}</small><h3>${escapeHTML(v.stall)}</h3><p>${escapeHTML(v.name)}</p><small>${escapeHTML(v.cat)}</small><button class="mini-btn vendor-view-btn" onclick="viewVendor('${escapeHTML(String(v.id))}')">${mi('visibility')} View Details</button></div></article>`;const vs=getVendors(),none='<div class="empty-note">No vendors have registered yet. Vendors appear here automatically once they create a Vendor account.</div>';$("#featuredVendors").innerHTML=vs.slice(0,3).map(card).join('')||none;$("#allVendors").innerHTML=vs.map(card).join('')||none}
const DEFAULT_GALLERY=["https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1485637701894-09ad422f6de6?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1533900298318-6b8da08a523e?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1601599963565-b7ba29c8e3ff?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1471193945509-9ad0617afabf?auto=format&fit=crop&w=800&q=80"].map((src,i)=>({id:'d'+i,src}));
