function updateSignupRoleUI(){const vend=$("#signupRole").value==='vendor';$("#vendorFieldsWrap").classList.toggle('hidden',!vend);$("#signupStall").required=vend;if(!vend){$("#signupStall").value='';$("#signupStallNo").value=''}const admin=$("#signupRole").value==='admin';["adminCodeWrap","adminCodeConfirmWrap","adminBiometricWrap"].forEach(id=>$("#"+id).classList.toggle('hidden',!admin));$("#adminCode").required=admin;$("#adminCodeConfirm").required=admin;if(!admin){$("#adminCode").value='';$("#adminCodeConfirm").value='';$("#enrollAdminBiometric").checked=false}}$("#signupRole").onchange=updateSignupRoleUI;updateSignupRoleUI();
async function enrollPasskey(account){if(!window.PublicKeyCredential||!navigator.credentials?.create){toast('Biometrics/passkeys need a supported browser on localhost or HTTPS.');return false}try{const challenge=crypto.getRandomValues(new Uint8Array(32));const userId=crypto.getRandomValues(new Uint8Array(16));const cred=await navigator.credentials.create({publicKey:{challenge,rp:{name:'Taytay Public Market'},user:{id:userId,name:account.email,displayName:account.name},pubKeyCredParams:[{alg:-7,type:'public-key'},{alg:-257,type:'public-key'}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required',residentKey:'preferred'},timeout:60000,attestation:'none'}});account.credentialId=btoa(String.fromCharCode(...new Uint8Array(cred.rawId)));return true}catch(e){toast('Biometric/passkey enrollment was cancelled or unavailable.');return false}}
async function verifyPasskey(account){if(!account?.credentialId||!window.PublicKeyCredential||!navigator.credentials?.get)return false;try{const raw=Uint8Array.from(atob(account.credentialId),c=>c.charCodeAt(0));const assertion=await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),allowCredentials:[{id:raw,type:'public-key'}],userVerification:'required',timeout:60000}});return !!assertion}catch(e){return false}}
$("#signupForm").onsubmit=async e=>{e.preventDefault();const role=$("#signupRole").value,email=$("#signupEmail").value.trim().toLowerCase(),pass=$("#signupPass").value;if(pass!==$("#signupConfirm").value)return toast('Passwords do not match.');if(pass.length<8)return toast('Password must be at least 8 characters.');if(role==='vendor'&&!$("#signupStall").value.trim())return toast('Please enter your stall name.');let securityCodeHash=null;if(role==='admin'){const code=$("#adminCode").value,confirm=$("#adminCodeConfirm").value;if(code.length<6)return toast('Admin Security Code must be at least 6 characters.');if(code!==confirm)return toast('Admin Security Codes do not match.');securityCodeHash=await hashPassword(code)}let accounts=getAccounts();if(accounts.some(a=>a.email===email))return toast('An account with this email already exists.');const newId=crypto.randomUUID?crypto.randomUUID():String(Date.now());const account={id:newId,name:$("#signupName").value.trim(),email,phone:$("#signupPhone").value.trim(),role,passwordHash:await hashPassword(pass),securityCodeHash,vendorId:role==='vendor'?newId:null,stall:role==='vendor'?$("#signupStall").value.trim():undefined,stallNo:role==='vendor'?$("#signupStallNo").value.trim():undefined,stallCat:role==='vendor'?$("#signupStallCat").value:undefined,credentialId:null};if(role==='admin'&&$("#enrollAdminBiometric").checked){await enrollPasskey(account)}accounts.push(account);saveAccounts(accounts);renderVendors();closeModal('signupModal');$("#signupForm").reset();toast('Account created. Please sign in.');selectedRole=role;$$('.role-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.role===role));updateLoginRoleUI();openModal('authModal')};
$("#loginForm").onsubmit=async e=>{e.preventDefault();const email=$("#loginEmail").value.trim().toLowerCase(),account=getAccounts().find(a=>a.email===email&&a.role===selectedRole);if(!account||account.passwordHash!==await hashPassword($("#loginPassword").value))return toast('Access denied: invalid credentials or role.');let adminVerified=false;if(account.role==='admin'){if(!account.securityCodeHash)return toast('This Admin account must be recreated with your own Security Code.');if(account.securityCodeHash!==await hashPassword($("#loginAdminCode").value))return toast('Access denied: incorrect Admin Security Code.');adminVerified=true}currentUser={id:account.id,name:account.name,email:account.email,phone:account.phone,role:account.role,vendorId:account.vendorId,adminVerified};sessionStorage.setItem('tpm_session',JSON.stringify(currentUser));closeModal('authModal');updateAuth();toast('Signed in.');route(account.role==='vendor'?'vendor-dashboard':account.role==='admin'?'admin-dashboard':'customer-dashboard')};
$("#biometricLogin").onclick=async()=>{const email=$("#loginEmail").value.trim().toLowerCase();if(!email)return toast('Enter your Admin email first.');const account=getAccounts().find(a=>a.email===email&&a.role==='admin');if(!account)return toast('Access denied: Admin account not found.');if(!account.credentialId)return toast('No biometric/passkey is enrolled for this Admin account.');if(!await verifyPasskey(account))return toast('Access denied: biometric/passkey verification failed.');currentUser={id:account.id,name:account.name,email:account.email,phone:account.phone,role:'admin',adminVerified:true};sessionStorage.setItem('tpm_session',JSON.stringify(currentUser));closeModal('authModal');updateAuth();toast('Biometric verification successful.');route('admin-dashboard')};
