function logout(){sessionStorage.removeItem('tpm_session');currentUser=null;updateAuth();toast('You have logged out.');route('home')}function updateAuth(){const navAuth=$("#navAuthBtn");if(navAuth)navAuth.textContent=currentUser?'Logout':'Log in';const sb=$("#settingsBtn");if(sb){sb.style.display=currentUser?'inline-flex':'none';sb.title=currentUser?`${currentUser.role.charAt(0).toUpperCase()+currentUser.role.slice(1)} Settings`:'Settings'}renderSides();renderFeatured();renderProducts();if(currentUser)renderNotifications();else{const dot=document.querySelector('#notifBtn .dot');if(dot)dot.style.display='none'}}
function mi(name){return `<span class="material-symbols-outlined">${name}</span>`}
function sideHTML(role){const common=`<div class="dash-user"><b>${escapeHTML(currentUser?.name||'Guest')}</b><small>${role}</small></div>`;if(role==='Vendor')return common+`<button data-route="vendor-dashboard">${mi('dashboard')} Dashboard</button><button data-route="vendor-inventory">${mi('inventory_2')} Products & Inventory</button><button data-route="products">${mi('storefront')} Browse Market</button><button data-route="reservations">${mi('event_note')} Customer Reservations</button><button data-route="profile">${mi('account_circle')} Vendor Profile</button><button data-route="settings">${mi('settings')} Settings</button><button onclick="logout()">${mi('logout')} Logout</button>`;if(role==='Admin')return common+`<button data-route="admin-dashboard">${mi('dashboard')} Dashboard</button><button onclick="openAdminManager('users')">${mi('group')} Users</button><button onclick="openAdminManager('vendors')">${mi('storefront')} Vendors</button><button onclick="openAdminManager('categories')">${mi('category')} Categories</button><button onclick="openAdminManager('gallery')">${mi('photo_library')} Gallery</button><button data-route="reservations">${mi('event_note')} Reservations</button><button data-route="profile">${mi('account_circle')} Admin Profile</button><button data-route="settings">${mi('settings')} Settings</button><button onclick="logout()">${mi('logout')} Logout</button>`;return common+`<button data-route="customer-dashboard">${mi('dashboard')} Dashboard</button><button data-route="products">${mi('storefront')} Products</button><button data-route="vendors">${mi('store')} Vendors</button><button data-route="reservations">${mi('event_note')} My Reservations</button><button data-route="profile">${mi('account_circle')} My Profile</button><button data-route="settings">${mi('settings')} Settings</button><button onclick="logout()">${mi('logout')} Logout</button>`}
function renderSides(){const ps=$("#portalSide");if(!ps)return;const role=currentUser?.role==='vendor'?'Vendor':currentUser?.role==='admin'?'Admin':'Customer';ps.dataset.role=currentUser?role.toLowerCase():'';ps.innerHTML=currentUser?sideHTML(role):'';const nd=$("#navDashboard");if(nd){nd.classList.toggle('hidden',!currentUser);if(currentUser)nd.dataset.route=currentUser.role==='vendor'?'vendor-dashboard':currentUser.role==='admin'?'admin-dashboard':'customer-dashboard'}}
function renderCustomerDashboard(){if(currentUser?.role!=='customer')return deny();const rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]').filter(r=>r.user===currentUser.email);const pending=rs.filter(r=>r.status==='Pending').length;$("#customerMetrics").innerHTML=[["Available Products",products.filter(p=>p.stock>0).length],["My Reservations",rs.length],["Pending",pending],["Total Reserved",money(rs.reduce((a,r)=>a+(+r.total||0),0))]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function renderRoleSettings(){if(!currentUser)return;const role=currentUser.role;const labels={customer:'Customer',vendor:'Vendor',admin:'Admin'};const title=document.querySelector('#settings .dash-title .kicker');if(title)title.textContent=(labels[role]||'Account').toUpperCase()+' PREFERENCES';const extra=$('#roleSettingsExtras');if(!extra)return;const roleText=role==='vendor'?'Edit your vendor name, contact number, and profile picture.':role==='admin'?'Edit your admin profile. Website logo and background remain Admin-only controls.':'Edit your customer name, contact number, and profile picture.';extra.innerHTML=`<div class="setting-card"><div><h3>${mi('manage_accounts')} Account & Profile</h3><p>${roleText}</p></div><button class="btn btn-outline" onclick="editProfile()">Edit Profile</button></div>${role==='admin'?`<div class="setting-card"><div><h3>${mi('image')} Website Logo & Appearance</h3><p>Only Admin can change the public website logo, hero background, name, and announcement.</p></div><button class="btn btn-outline" data-route="admin-dashboard">Open Admin</button></div>`:''}`}
function profilePhotoKey(){return currentUser?'tpm_profile_'+currentUser.id:''}
function getProfilePhoto(){if(!currentUser)return null;return localStorage.getItem(profilePhotoKey())||(currentUser.role==='admin'?localStorage.getItem('tpm_adminProfile'):null)}
function renderProfile(){if(!currentUser)return;const photo=getProfilePhoto();$('#profileContent').innerHTML=`<div class="profile-card"><div class="profile-avatar">${photo?`<img src="${photo}" alt="Profile">`:escapeHTML(currentUser.name.charAt(0).toUpperCase())}</div><div><small>${escapeHTML(currentUser.role.toUpperCase())}</small><h2>${escapeHTML(currentUser.name)}</h2><p>${escapeHTML(currentUser.email)}</p><p>${escapeHTML(currentUser.phone||'')}</p><button class="btn btn-outline" onclick="editProfile()">${mi('edit')} Edit Profile</button></div></div>`}
function setProfilePreview(src){const box=$('#profilePhotoPreview');$('#profilePhotoData').value=src||'';if(src){box.style.backgroundImage=`url("${src}")`;box.classList.add('has-image');box.innerHTML=''}else{box.style.backgroundImage='';box.classList.remove('has-image');box.innerHTML=`${mi('account_circle')}<small>Keep current profile picture</small>`}}
window.editProfile=()=>{if(!currentUser)return;const isV=currentUser.role==='vendor';$('#profileVendorWrap').classList.toggle('hidden',!isV);if(isV){const av=getAccounts().find(x=>x.id===currentUser.id)||{};$('#profileStall').value=av.stall||'';$('#profileStallNo').value=av.stallNo&&av.stallNo!=='—'?av.stallNo:''}$('#profileEditName').value=currentUser.name||'';$('#profileEditPhone').value=currentUser.phone||'';setProfilePreview(getProfilePhoto());openModal('profileEditModal')};
function compressProfileImage(file,maxSize=720,quality=.78){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Unable to read image.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Invalid image file.'));img.onload=()=>{let w=img.width,h=img.height;const scale=Math.min(1,maxSize/Math.max(w,h));w=Math.max(1,Math.round(w*scale));h=Math.max(1,Math.round(h*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',quality))};img.src=reader.result};reader.readAsDataURL(file)})}
async function profilePhotoSelected(input){const file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Please select an image file.');input.value='';return}if(file.size>8*1024*1024){toast('Profile picture must be 8 MB or smaller.');input.value='';return}try{setProfilePreview(await compressProfileImage(file))}catch(err){console.error(err);toast('Could not load that profile picture.')}}
