$('#profileEditForm').addEventListener('submit',e=>{e.preventDefault();if(!currentUser)return;const btn=$('#saveProfileBtn');const name=$('#profileEditName').value.trim();if(!name){toast('Full name is required.');$('#profileEditName').focus();return}btn.disabled=true;const oldText=btn.textContent;btn.textContent='Saving...';try{currentUser.name=name;currentUser.phone=$('#profileEditPhone').value.trim();const photo=$('#profilePhotoData').value;if(photo){try{localStorage.setItem(profilePhotoKey(),photo);if(currentUser.role==='admin')localStorage.setItem('tpm_adminProfile',photo)}catch(storageError){console.error(storageError);toast('Profile photo is too large for browser storage. Try another photo.');return}}sessionStorage.setItem('tpm_session',JSON.stringify(currentUser));let accounts=getAccounts(),a=accounts.find(x=>x.id===currentUser.id);if(a){a.name=currentUser.name;a.phone=currentUser.phone;if(a.role==='vendor'){const sn=$('#profileStall').value.trim();if(sn)a.stall=sn;a.stallNo=$('#profileStallNo').value.trim()}saveAccounts(accounts)}closeModal('profileEditModal');renderVendors();renderProducts();renderFeatured();renderProfile();renderSides();renderRoleSettings();if(currentUser.role==='vendor')renderVendorDashboard();if(currentUser.role==='customer')renderCustomerDashboard();if(currentUser.role==='admin')renderAdmin();toast('Profile saved successfully.')}catch(err){console.error(err);toast('Could not save profile. Please try again.')}finally{btn.disabled=false;btn.textContent=oldText}});
function reserve(id){if(!currentUser)return openModal('authModal'),toast('Please sign in first to reserve.');if(currentUser.role!=='customer')return toast('Only customers can reserve products.');const p=products.find(x=>x.id===id);if(currentUser.role==='vendor'&&p.vendorId===(currentUser.vendorId))return toast('You cannot reserve your own product.');$("#reserveProductId").value=id;$("#reserveTitle").textContent=`Reserve ${p.name}`;$("#reserveSummary").innerHTML=`<b>${escapeHTML(p.name)}</b><br><small>${escapeHTML(vendorOf(p.vendorId).stall)} • ${money(p.price)}/${p.unit}</small>`;$("#reserveQty").max=p.stock;$("#reserveQty").value=1;$("#pickupDate").min=new Date().toISOString().split('T')[0];updateReserveTotal();openModal('reserveModal')}
$("#reserveQty").oninput=updateReserveTotal;function updateReserveTotal(){const p=products.find(x=>x.id==$("#reserveProductId").value);if(p)$("#reserveTotal").textContent=money(p.price*(+$("#reserveQty").value||0))}
$("#reserveForm").onsubmit=e=>{e.preventDefault();if(currentUser?.role!=='customer')return toast('Only customers can reserve products.');const p=products.find(x=>x.id==$("#reserveProductId").value),q=+$("#reserveQty").value;if(currentUser.role==='vendor'&&p.vendorId===(currentUser.vendorId))return toast('You cannot reserve your own product.');if(q>p.stock)return toast('Requested quantity exceeds available stock.');let rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]');let ref='TPM-RES-'+Date.now();rs.unshift({ref,productId:p.id,product:p.name,vendor:vendorOf(p.vendorId).stall,vendorId:p.vendorId,qty:q,total:p.price*q,pickup:$("#pickupDate").value,note:$("#reserveNote").value,status:'Pending',user:currentUser.email,customer:currentUser.name,phone:currentUser.phone||''});localStorage.setItem('tpm_reservations',JSON.stringify(rs));p.stock-=q;saveProducts();closeModal('reserveModal');renderFeatured();renderProducts();toast('Reservation submitted!')};
function renderReservations(){const all=JSON.parse(localStorage.getItem('tpm_reservations')||'[]'),role=currentUser?.role,vid=currentUser.vendorId;let rs=[];if(role==='customer')rs=all.filter(r=>r.user===currentUser.email);else if(role==='vendor')rs=all.filter(r=>r.vendorId===vid&&r.user!==currentUser.email);else if(role==='admin')rs=all;const k=$('#reservations .dash-title .kicker'),h=$('#reservations .dash-title h1');if(k)k.textContent=role==='vendor'?'CUSTOMER ORDERS':role==='admin'?'ALL RESERVATIONS':'MY ACCOUNT';if(h)h.textContent=role==='vendor'?'Customer Reservations':role==='admin'?'All Reservations':'My Reservations';const cls=s=>s==='Declined'?'out':s==='Pending'?'low':'';const who=r=>`${escapeHTML(r.customer||r.user)}${r.phone?' • '+escapeHTML(r.phone):''}<br><small>${escapeHTML(r.user)}</small>`;const acts=r=>{const b=(st,l,d)=>`<button class="mini-btn${d?' danger':''}" onclick="setReservationStatus('${r.ref}','${st}')">${l}</button>`;if(r.status==='Pending')return b('Confirmed','Confirm')+b('Declined','Decline',1);if(r.status==='Confirmed')return b('Ready for Pickup','Mark Ready for Pickup')+b('Declined','Decline',1);if(r.status==='Ready for Pickup')return b('Completed','Mark Picked Up');return''};let summary='';if(role==='vendor'){const c=s=>rs.filter(r=>r.status===s).length;summary=`<div class="metric-grid" style="margin-bottom:18px"><div class="metric"><span>Pending</span><b>${c('Pending')}</b></div><div class="metric"><span>Confirmed</span><b>${c('Confirmed')}</b></div><div class="metric"><span>Ready for Pickup</span><b>${c('Ready for Pickup')}</b></div><div class="metric"><span>Completed</span><b>${c('Completed')}</b></div></div>`}const empty=role==='vendor'?'<div class="panel"><p>No customer reservations yet. When a customer reserves one of your products, it will appear here.</p></div>':role==='admin'?'<div class="panel"><p>No reservations yet.</p></div>':'<div class="panel"><p>No reservations yet.</p><button class="btn btn-primary" data-route="products">Browse Products</button></div>';$("#reservationList").innerHTML=summary+(rs.length?rs.map(r=>{let body;if(role==='customer'){body=`<div><b>${escapeHTML(r.product)}</b><br><small>${escapeHTML(r.ref)} • ${escapeHTML(r.vendor)}<br>Pickup: ${escapeHTML(r.pickup)} • Qty: ${r.qty}</small>${r.status==='Pending'?`<div class="reservation-actions"><button class="mini-btn" onclick="editReservation('${r.ref}')">Edit</button><button class="mini-btn danger" onclick="deleteReservation('${r.ref}')">Delete</button></div>`:''}</div>`}else if(role==='vendor'){body=`<div><b>${escapeHTML(r.product)}</b> <span class="status">Customer Order</span><br><small>${escapeHTML(r.ref)}<br>Customer: ${who(r)}<br>Pickup: ${escapeHTML(r.pickup)} • Qty: ${r.qty}${r.note?'<br>Note: '+escapeHTML(r.note):''}</small><div class="reservation-actions">${acts(r)}</div></div>`}else{body=`<div><b>${escapeHTML(r.product)}</b><br><small>${escapeHTML(r.ref)} • ${escapeHTML(r.vendor)}<br>Customer: ${who(r)}<br>Pickup: ${escapeHTML(r.pickup)} • Qty: ${r.qty}</small></div>`}return `<div class="reservation-card">${body}<div><span class="status ${cls(r.status)}">${escapeHTML(r.status)}</span><b>${money(r.total)}</b></div></div>`}).join(''):empty)}
window.setReservationStatus=(ref,status)=>{if(currentUser?.role!=='vendor')return deny();const rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]'),r=rs.find(x=>x.ref===ref&&x.vendorId===(currentUser.vendorId));if(!r)return toast('Reservation not found.');const allowed={'Pending':['Confirmed','Declined'],'Confirmed':['Ready for Pickup','Declined'],'Ready for Pickup':['Completed']};if(!(allowed[r.status]||[]).includes(status))return toast('That status change is not allowed.');if(status==='Declined'&&!confirm('Decline this reservation? The stock will be returned.'))return;if(status==='Declined'){const p=products.find(x=>x.id===r.productId);if(p){p.stock+=r.qty;saveProducts()}}r.status=status;localStorage.setItem('tpm_reservations',JSON.stringify(rs));renderReservations();renderProducts();renderFeatured();renderNotifications();toast('Reservation marked as '+status+'.')};
window.editReservation=ref=>{if(currentUser?.role!=='customer')return deny();const r=JSON.parse(localStorage.getItem('tpm_reservations')||'[]').find(x=>x.ref===ref&&x.user===currentUser.email);if(!r)return toast('Reservation not found.');if(r.status!=='Pending')return toast('Only pending reservations can be edited.');$("#editReservationRef").value=r.ref;$("#editReservationQty").value=r.qty;$("#editReservationPickup").value=r.pickup;$("#editReservationPickup").min=new Date().toISOString().split('T')[0];$("#editReservationNote").value=r.note||'';openModal('editReservationModal')};
$("#editReservationForm").onsubmit=e=>{e.preventDefault();let rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]'),r=rs.find(x=>x.ref===$("#editReservationRef").value&&x.user===currentUser?.email);if(!r)return toast('Access denied.');const p=products.find(x=>x.id===r.productId);const newQty=+$("#editReservationQty").value,diff=newQty-r.qty;if(diff>0&&(!p||diff>p.stock))return toast('Not enough stock for that quantity.');if(p){p.stock-=diff;saveProducts();r.total=p.price*newQty}r.qty=newQty;r.pickup=$("#editReservationPickup").value;r.note=$("#editReservationNote").value;localStorage.setItem('tpm_reservations',JSON.stringify(rs));closeModal('editReservationModal');renderReservations();renderProducts();renderFeatured();toast('Reservation updated.')};
window.deleteReservation=ref=>{if(currentUser?.role!=='customer')return deny();let rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]'),i=rs.findIndex(x=>x.ref===ref&&x.user===currentUser.email);if(i<0)return toast('Access denied.');if(rs[i].status!=='Pending')return toast('Only pending reservations can be deleted.');if(!confirm('Delete this reservation?'))return;const r=rs[i],p=products.find(x=>x.id===r.productId);if(p){p.stock+=r.qty;saveProducts()}rs.splice(i,1);localStorage.setItem('tpm_reservations',JSON.stringify(rs));renderReservations();renderProducts();renderFeatured();toast('Reservation deleted.')};
