window.viewVendor=id=>{const v=getVendors().find(x=>x.id===id);if(!v)return;const count=products.filter(p=>p.vendorId===id).length;$('#vendorDetailContent').innerHTML=`<div class="vendor-detail-head"><div class="vendor-avatar">${mi('storefront')}</div><div><span class="kicker">STALL ${escapeHTML(v.no)}</span><h2>${escapeHTML(v.stall)}</h2><p>${escapeHTML(v.name)}</p></div></div><div class="detail-info"><span>${mi('category')} ${escapeHTML(v.cat)}</span><span>${mi('inventory_2')} ${count} listed product${count!==1?'s':''}</span><span>${mi('location_on')} Taytay Public Market, Palawan</span></div><div class="detail-actions"><button class="btn btn-outline" onclick="closeModal('vendorDetailModal')">${mi('arrow_back')} Back</button><a class="btn btn-primary" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=Taytay+Public+Market+Palawan">${mi('map')} Open Map</a></div>`;openModal('vendorDetailModal')};
function buildNotifications(){if(!currentUser)return[];const rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]');let notes=[];if(currentUser.role==='admin')notes=rs.slice(0,20).map(r=>({icon:'event_note',title:'Reservation activity',text:`${r.product} • ${r.qty} item(s) • ${r.status}`,time:r.ref}));else if(currentUser.role==='vendor')notes=rs.filter(r=>r.vendorId===(currentUser.vendorId)&&r.user!==currentUser.email).slice(0,20).map(r=>({icon:r.user===currentUser.email?'shopping_bag':'notifications',title:r.user===currentUser.email?'Your reservation':'Customer reservation',text:`${r.product} • Pickup ${r.pickup} • ${r.status}`,time:r.ref}));else notes=rs.filter(r=>r.user===currentUser.email).slice(0,20).map(r=>({icon:'event_available',title:'Reservation update',text:`${r.product} • Pickup ${r.pickup} • ${r.status}`,time:r.ref}));return notes}
function renderNotifications(){const notes=buildNotifications();$('#notificationList').innerHTML=notes.length?notes.map(n=>`<div class="notification-item"><div class="notification-icon">${mi(n.icon)}</div><div><b>${escapeHTML(n.title)}</b><p>${escapeHTML(n.text)}</p><small>${escapeHTML(n.time)}</small></div></div>`).join(''):'<div class="empty-state">'+mi('notifications_none')+'<p>No notifications yet.</p></div>';const dot=document.querySelector('#notifBtn .dot');if(dot)dot.style.display=notes.length?'block':'none'}
