function renderVendorDashboard(){if(currentUser?.role!=='vendor')return deny();if($('#vendorGreeting'))$('#vendorGreeting').textContent=`Good day, ${currentUser.name.split(' ')[0]}!`;const vid=currentUser.vendorId,mine=products.filter(p=>p.vendorId===vid),rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]').filter(r=>r.vendorId===vid&&r.user!==currentUser.email);$("#vendorMetrics").innerHTML=[["Total Products",mine.length],["Available",mine.filter(p=>statusOf(p)==='Available').length],["Low Stock",mine.filter(p=>statusOf(p)==='Low Stock').length],["Reservations",rs.length]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');$("#vendorProductRows").innerHTML=mine.map(p=>`<tr><td><div class="table-product"><div class="table-thumb" style="background-image:url('${escapeHTML(p.image)}')"></div><b>${escapeHTML(p.name)}</b></div></td><td>${money(p.price)}/${p.unit}</td><td>${p.stock}</td><td>${statusOf(p)}</td><td><button class="mini-btn" onclick="editProduct(${p.id})">Edit</button> <button class="mini-btn danger" onclick="deleteProduct(${p.id})">Delete</button></td></tr>`).join('')}
