async function productPhotoSelected(input){const file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Please select an image file.');if(file.size>25*1024*1024)return toast('Product photo must be 25 MB or smaller.');try{setProductPreview(await resizeImageFile(file,900,.75))}catch(err){console.error(err);toast('Could not load that photo.')}}
