$("#addProductBtn").onclick=()=>{if(currentUser?.role!=='vendor')return deny();$("#productForm").reset();$("#editProductId").value='';setProductPreview('');$("#productModalTitle").textContent='Add Product';openModal('productModal')};window.editProduct=id=>{const p=products.find(x=>x.id===id&&x.vendorId===(currentUser.vendorId));if(!p||currentUser?.role!=='vendor')return deny();$("#editProductId").value=id;$("#pName").value=p.name;$("#pCategory").value=p.category;$("#pPrice").value=p.price;$("#pUnit").value=p.unit;$("#pStock").value=p.stock;setProductPreview(p.image);$("#pDesc").value=p.desc;$("#productModalTitle").textContent='Edit Product';openModal('productModal')};window.deleteProduct=id=>{if(currentUser?.role!=='vendor')return deny();const vid=currentUser.vendorId;if(!products.some(p=>p.id===id&&p.vendorId===vid))return deny();if(confirm('Are you sure you want to delete this product?')){products=products.filter(p=>p.id!==id);saveProducts();renderVendorDashboard();renderFeatured();renderProducts();toast('Product deleted.')}};
$("#productForm").onsubmit=e=>{e.preventDefault();if(currentUser?.role!=='vendor')return deny();const id=+$("#editProductId").value,vid=currentUser.vendorId,image=$("#pImage").value;if(!image)return toast('Please choose or capture a product picture.');const data={name:$("#pName").value.trim(),category:$("#pCategory").value,price:+$("#pPrice").value,unit:$("#pUnit").value,stock:+$("#pStock").value,image,desc:$("#pDesc").value.trim(),vendorId:vid};if(id){const p=products.find(p=>p.id===id&&p.vendorId===vid);if(!p)return deny();Object.assign(p,data)}else products.push({id:Date.now(),...data});saveProducts();closeModal('productModal');renderVendorDashboard();renderFeatured();renderProducts();toast(id?'Product updated.':'Product added successfully.')};
