window.openAdminManager=type=>{if(currentUser?.role!=='admin'||!currentUser.adminVerified)return deny();const accounts=getAccounts(),titles={users:'User Management',vendors:'Vendor Management',categories:'Categories',gallery:'Gallery Management'};$("#adminManagerTitle").textContent=titles[type]||'Management';let html='';if(type==='users'||type==='vendors'){const role=type==='users'?'customer':'vendor',list=accounts.filter(a=>a.role===role);html=list.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody>${list.map(a=>`<tr><td>${escapeHTML(a.name)}</td><td>${escapeHTML(a.email)}</td><td>${escapeHTML(a.role)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No accounts yet.</p>'}else if(type==='categories'){html=`<div class="quick-list">${categories.map(c=>`<button onclick="toast('Category: ${escapeHTML(c[0])}')"><span>${mi('category')} ${escapeHTML(c[0])}</span><span>${products.filter(p=>p.category===c[0]).length} products</span></button>`).join('')}</div>`}else{renderGalleryManager();openModal('adminManagerModal');return}$("#adminManagerContent").innerHTML=html;openModal('adminManagerModal')}
function fileToDataURL(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
$("#customForm").onsubmit=async e=>{e.preventDefault();if(currentUser?.role!=='admin'||!currentUser.adminVerified)return deny();const name=$("#siteNameInput").value.trim(),tag=$("#taglineInput").value.trim();localStorage.setItem('tpm_siteName',name);localStorage.setItem('tpm_tagline',tag);localStorage.setItem('tpm_announcement',$("#announcementInput").value.trim());const [logo,bg,profile]=await Promise.all([fileToDataURL($("#logoInput").files[0]),fileToDataURL($("#backgroundInput").files[0]),fileToDataURL($("#adminProfileInput").files[0])]);if(logo)localStorage.setItem('tpm_logo',logo);if(bg)localStorage.setItem('tpm_background',bg);if(profile){localStorage.setItem('tpm_adminProfile',profile);localStorage.setItem(profilePhotoKey(),profile)}applyCustomization();toast('Website customization saved.')};
function applyCustomization(){const name=localStorage.getItem('tpm_siteName')||'Taytay Public Market',tag=localStorage.getItem('tpm_tagline')||'Fresh Products. Local Vendors. One Community.',logo=localStorage.getItem('tpm_logo'),bg=localStorage.getItem('tpm_background');$("#brandName").textContent=name;document.title=name;const tagEl=document.querySelector('[data-i18n="tagline"]');if(tagEl)tagEl.textContent=tag;if(logo)$$('.brand-mark').forEach(el=>{el.innerHTML=`<img class="brand-logo-img" src="${logo}" alt="${escapeHTML(name)} logo">`});if(bg)document.querySelector('.hero').style.backgroundImage=`linear-gradient(90deg,rgba(5,45,27,.94) 0%,rgba(8,53,32,.78) 47%,rgba(8,53,32,.2) 78%),url('${bg}')`;$("#siteNameInput").value=name;$("#taglineInput").value=tag}
const translations={en:{home:'Home',products:'Products',vendors:'Vendors',about:'About',gallery:'Gallery',contact:'Contact',welcome:'Welcome to Taytay Public Market',tagline:'Fresh Products. Local Vendors. One Community.',explore:'Explore Products',viewVendors:'View Vendors'},fil:{home:'Tahanan',products:'Mga Produkto',vendors:'Mga Tindero',about:'Tungkol',gallery:'Galeriya',contact:'Kontak',welcome:'Maligayang pagdating sa Taytay Public Market',tagline:'Sariwang Produkto. Lokal na Tindero. Isang Komunidad.',explore:'Tingnan ang Produkto',viewVendors:'Tingnan ang mga Tindero'}};
