$("#aiFab").onclick=()=>$("#aiPanel").classList.toggle('open');$("#aiClose").onclick=()=>$("#aiPanel").classList.remove('open');$$('.quick-prompts button').forEach(b=>b.onclick=()=>{$("#aiInput").value=b.textContent;$("#aiForm").requestSubmit()});$("#aiForm").onsubmit=e=>{e.preventDefault();const q=$("#aiInput").value.trim();if(!q)return;$("#aiMessages").insertAdjacentHTML('beforeend',`<div class="msg user">${escapeHTML(q)}</div>`);$("#aiInput").value='';let low=q.toLowerCase(),matches=products.filter(p=>low.includes(p.name.toLowerCase())||p.name.toLowerCase().split(' ').some(w=>w.length>3&&low.includes(w))||low.includes(p.category.toLowerCase()));let ans=matches.length?matches.map(p=>`${escapeHTML(p.name)}: ${statusOf(p)}, ${money(p.price)}/${p.unit}, ${p.stock} ${p.unit} in stock at ${escapeHTML(vendorOf(p.vendorId).stall)}.`).join('<br>'):"I couldn't find that in the current market inventory.";setTimeout(()=>{$("#aiMessages").insertAdjacentHTML('beforeend',`<div class="msg bot">${ans}</div>`);$("#aiMessages").scrollTop=$("#aiMessages").scrollHeight},200)};
function migrateData(){try{const SEED=['Fresh Tomatoes','Bangus','Pechay','Fresh Chicken','Mangoes','Rice - Premium','Galunggong','Red Onions'];const accs=getAccounts();let changed=false,legacyId=null;accs.forEach(a=>{if(a.role==='vendor'&&(a.vendorId===1||!a.vendorId)){if(legacyId===null)legacyId=a.id;a.vendorId=a.id;if(!a.stall)a.stall=a.name+"'s Stall";changed=true}});if(changed)saveAccounts(accs);const target=legacyId||(accs.find(a=>a.role==='vendor')||{}).id;const n0=products.length;products=products.filter(p=>!(typeof p.id==='number'&&p.id<=8));let pc=products.length!==n0;products=products.filter(p=>{if(typeof p.vendorId==='number'){if(!target){pc=true;return false}p.vendorId=target;pc=true}return true});if(pc)saveProducts();const rs=JSON.parse(localStorage.getItem('tpm_reservations')||'[]');let rc=false;const rs2=rs.filter(r=>{if(typeof r.vendorId==='number'){rc=true;if(!target||r.vendorId!==1)return false;r.vendorId=target}return true});if(rc)localStorage.setItem('tpm_reservations',JSON.stringify(rs2));if(currentUser?.role==='vendor'){const a=accs.find(x=>x.id===currentUser.id);if(a&&currentUser.vendorId!==a.vendorId){currentUser.vendorId=a.vendorId;sessionStorage.setItem('tpm_session',JSON.stringify(currentUser))}}}catch(e){console.error('migrate',e)}}
function init(){migrateData();renderCategories();renderFeatured();renderProducts();renderVendors();updateAuth();applyLang(localStorage.getItem('tpm_lang')||'en');applyTheme(localStorage.getItem('tpm_theme')==='dark');applyCustomization();const h=location.hash.replace('#','');if(h)route(h)}init();

/* ===== In-app camera (opens device camera, not file manager) ===== */
(function(){
  const modal=$('#cameraModal'),video=$('#cameraVideo'),errBox=$('#cameraError');
  let stream=null,facing='environment',target=null;
  function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}video.srcObject=null}
  function closeCamera(){modal.classList.remove('open');stopCamera()}
  async function startCamera(){
    stopCamera();errBox.textContent='';
    try{
      stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing},width:{ideal:1280},height:{ideal:960}},audio:false});
      video.classList.toggle('mirror',facing==='user');
      video.srcObject=stream;await video.play().catch(()=>{});
    }catch(err){
      console.error(err);
      errBox.textContent=err.name==='NotAllowedError'||err.name==='SecurityError'?'Camera access was blocked. Allow camera permission in your browser settings, then try again.':err.name==='NotFoundError'||err.name==='OverconstrainedError'?'No camera was found on this device.':'Could not start the camera.';
    }
  }
  function openCamera(opts){
    target=opts;facing=opts.facing;
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){
      // Fallback for old browsers / non-secure pages: native capture input (works on phones)
      toast('Live camera is not available here. Use HTTPS or localhost.');
      opts.fallback.click();return;
    }
    modal.classList.add('open');startCamera();
  }
  function snap(){
    if(!stream||!video.videoWidth)return toast('Camera is not ready yet.');
    const max=target.maxSize,scale=Math.min(1,max/Math.max(video.videoWidth,video.videoHeight));
    const w=Math.round(video.videoWidth*scale),h=Math.round(video.videoHeight*scale);
    const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(video,0,0,w,h);
    target.onPhoto(c.toDataURL('image/jpeg',target.quality));closeCamera();
  }
  $('#pCameraBtn').addEventListener('click',()=>openCamera({facing:'environment',maxSize:1280,quality:.82,fallback:$('#pCameraFile'),onPhoto:setProductPreview}));
  $('#profileCameraBtn').addEventListener('click',()=>openCamera({facing:'user',maxSize:720,quality:.78,fallback:$('#profileCameraFile'),onPhoto:setProfilePreview}));
  $('#cameraSnap').addEventListener('click',snap);
  $('#cameraSwitch').addEventListener('click',()=>{facing=facing==='environment'?'user':'environment';startCamera()});
  $('#cameraCancel').addEventListener('click',closeCamera);$('#cameraCloseX').addEventListener('click',closeCamera);
  // Stop the camera if the modal is closed by tapping the backdrop
  new MutationObserver(()=>{if(!modal.classList.contains('open'))stopCamera()}).observe(modal,{attributes:true,attributeFilter:['class']});
})();

/* ===== Admin Gallery Management (add / delete photos) ===== */
function renderGalleryManager(){const list=getGallery();$("#adminManagerContent").innerHTML=`<div class="gallery-admin-bar"><label class="btn btn-primary photo-pick"><span class="material-symbols-outlined">add_photo_alternate</span> Add Photos<input type="file" id="galleryUpload" accept="image/*" multiple hidden></label><button type="button" class="btn btn-outline" id="galleryReset">Reset to default</button><small>${list.length} photo${list.length!==1?'s':''} • shown on the public Gallery page</small></div><div class="gallery-admin-grid">${list.length?list.map(x=>`<div class="gallery-admin-item" style="background-image:url('${x.src}')"><button type="button" class="gallery-del" data-gdel="${escapeHTML(x.id)}" title="Delete photo" aria-label="Delete photo"><span class="material-symbols-outlined">delete</span></button></div>`).join(''):'<p>No photos yet. Click "Add Photos" to upload.</p>'}</div>`}
function resizeImageFile(file,max=1200,quality=.8){return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(new Error('read'));r.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('img'));img.onload=()=>{const s=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*s)),h=Math.max(1,Math.round(img.height*s)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',quality))};img.src=r.result};r.readAsDataURL(file)})}
$("#adminManagerContent").addEventListener('change',async e=>{if(e.target.id!=='galleryUpload')return;if(currentUser?.role!=='admin'||!currentUser.adminVerified)return deny();const files=[...e.target.files].filter(f=>f.type.startsWith('image/'));e.target.value='';if(!files.length)return toast('Please choose image files.');const list=[...getGallery()];let added=0;for(const f of files){try{list.push({id:'g'+Date.now()+Math.random().toString(36).slice(2,7),src:await resizeImageFile(f)});added++}catch(err){console.error(err)}}if(!added)return toast('Could not read those images.');if(saveGallery(list)){renderGalleryGrid();renderGalleryManager();toast(added+' photo'+(added>1?'s':'')+' added to the gallery.')}});
$("#adminManagerContent").addEventListener('click',e=>{const del=e.target.closest('[data-gdel]');if(del){if(currentUser?.role!=='admin'||!currentUser.adminVerified)return deny();if(!confirm('Delete this photo from the gallery?'))return;if(saveGallery(getGallery().filter(x=>x.id!==del.dataset.gdel))){renderGalleryGrid();renderGalleryManager();toast('Photo deleted.')}return}if(e.target.closest('#galleryReset')){if(!confirm('Reset the gallery to the default photos?'))return;localStorage.removeItem('tpm_gallery');renderGalleryGrid();renderGalleryManager();toast('Gallery reset to default.')}});
